CREATE TABLE "NotificationDigestItem" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"alertId" TEXT NOT NULL,"type" TEXT NOT NULL,"severity" INTEGER NOT NULL,"title" TEXT NOT NULL,"message" TEXT NOT NULL,"href" TEXT,"status" TEXT NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"digestedAt" TIMESTAMP(3),CONSTRAINT "NotificationDigestItem_pkey" PRIMARY KEY ("id"));CREATE UNIQUE INDEX "NotificationDigestItem_alertId_key" ON "NotificationDigestItem"("alertId");CREATE INDEX "NotificationDigestItem_userId_status_createdAt_idx" ON "NotificationDigestItem"("userId","status","createdAt");